// clang-format off
// MiniMax-H3 quantized full MLP for SM120 (GB202: RTX 5090 / RTX PRO 6000 Blackwell), generated from the
// kernel schedules.  Three launches per call (plus one memset of the FC2 tile flags):
//   1. norm_adaln_quant_{fp8,nvfp4}: RMSNorm(x) * w, indexed AdaLN (shift[i] + n * (1 + scale[i]) with an
//      int64 per-row table index; rows whose index lies outside [0, rows) are zero), then per-token E4M3
//      (scale = amax / 448) or block-16 NVFP4 (FlashInfer fp4_quantize semantics) quantization.
//   2. FC1 + SwiGLU (5376 -> 14336): persistent 128 x 128 output tiles over the prepacked FC1 weight (the NVFP4
//      kernel feeds its three-stage TMA ring from one producer warpgroup placed last and consumes it with two MMA
//      warpgroups at 224 registers; the FP8 kernels issue the TMA loads from MMA warp 0, 256 threads),
//      mma.sync e4m3 (legacy form on the RTX PRO 6000, kind::mxf8f6f4 with unit UE8M0 scales on GeForce
//      GB202 -- the same FP32-accumulating contraction at twice the issue rate there) or kind::mxf4nvf4
//      block-scaled; the FP8 form writes y = BF16(BF16(silu(h_gate)) * h_up) as BF16 [M, 14336], the NVFP4
//      kernel stages each pass's BF16 y through a 2 x 4 KiB swizzled ring and two spare warps of the producer
//      warpgroup quantize it (block-16 E2M1 codes + dense UE4M3 scales under the static y global scale).
//   3. FC2 (14336 -> 5376) with the fused epilogue: persistent 256 x 128 tiles, a three-stage 64-byte
//      swizzled TMA ring, one producer warpgroup (TMA warp + three quantization warps that stream the BF16
//      y rows into E4M3 + per-token scales in M-tile order and publish per-tile ready flags; idle for the
//      pre-quantized NVFP4 operands) and two MMA warpgroups; the epilogue dequantizes, forms
//      p = BF16(gate[idx] * o) and writes out = BF16(residual + p) (out may alias residual or x).
// Device code: TMA, ldmatrix, mma.sync (e4m3 / kind::mxf8f6f4 / kind::mxf4nvf4), mbarrier pipelines, setmaxnreg.
#include <cuda.h>
#include <cuda_bf16.h>
#include <cuda_fp8.h>

#include <cstdint>

static_assert(sizeof(CUtensorMap) == 128, "CUDA tensor-map ABI size mismatch");
static_assert(alignof(CUtensorMap) >= 64, "CUDA tensor-map ABI requires at least 64-byte alignment");

namespace h3_mlp_norm_adaln_quant_fp8_sm120a {

__device__ __forceinline__ int make_warp_uniform(int x) {
    int result;
    asm volatile("shfl.sync.idx.b32 %0, %1, 0, 0x1F, 0xFFFFFFFF;"
                 : "=r"(result) : "r"(x));
    return result;
}

#define H3_MLP_INF CUDART_INF_F
#define NUM_MAIN_STAGES 1
#define SMEM_PARTIALS_OFF 0
#define SMEM_PARTIALS_STAGE_BYTES 32
#define SMEM_PARTIALS_STRIDE 32
#define SMEM_AMAX_PARTIALS_OFF 32
#define SMEM_AMAX_PARTIALS_STAGE_BYTES 32
#define SMEM_AMAX_PARTIALS_STRIDE 32
#define SMEM_TOTAL 128
#define THREADS 128
#define LAUNCH_MIN_BLOCKS 4

#include <math_constants.h>

__global__ __launch_bounds__(THREADS, LAUNCH_MIN_BLOCKS) void
kernel_h3_mlp_norm_adaln_quant_fp8(__nv_bfloat16* __restrict__ x, __nv_bfloat16* __restrict__ x_norm_weight, __nv_bfloat16* __restrict__ adaln_scale, __nv_bfloat16* __restrict__ adaln_shift, long long* __restrict__ adaln_index, unsigned int* __restrict__ act_q, float* __restrict__ act_scale, int M, int adaln_rows, long long adaln_row_stride, float eps)
{
    const int tid = threadIdx.x;
    const int warp = make_warp_uniform(tid / 32);
    const int lane = tid % 32;

    extern __shared__ __align__(1024) char smem_raw[];
    int smem;
    smem = (int)(unsigned long long)__cvta_generic_to_shared(smem_raw);

    const int bid = blockIdx.x;
    const int num_bids = gridDim.x;

    const int cta_rank = 0;

    // Kernel setup ops
    float* partials = reinterpret_cast<float*>(smem_raw + SMEM_PARTIALS_OFF);
    const int partials_addr = smem + SMEM_PARTIALS_OFF;
    float* amax_partials = reinterpret_cast<float*>(smem_raw + SMEM_AMAX_PARTIALS_OFF);
    const int amax_partials_addr = smem + SMEM_AMAX_PARTIALS_OFF;

    // === Task calls (dependency order) ===
    long long rows64 = (long long)adaln_rows;
    long long zero64 = (long long)0;
    unsigned long long stride64 = (unsigned long long)adaln_row_stride;
    #pragma unroll 1
    for (int row = bid; row < M; row += num_bids) {
        float x_vals[48];
        float a_vals[48];
        float total = 0.0f;
        for (int i = 0; i < 3; i++) {
            int chunk = tid + i * 128;
            for (int e = 0; e < 16; e++) {
                x_vals[i * 16 + e] = 0.0f;
            }
            if (chunk < 336) {
                int col = chunk * 16;
                float _vec_load_0[8];
                {
                    const uint4* _vptr_0 = reinterpret_cast<const uint4*>(x + (row * 5376 + col) + 0);
                    uint4 _vld_0[1];
                    #pragma unroll
                    for (int _blk = 0; _blk < 1; _blk++) {
                        _vld_0[_blk] = _vptr_0[_blk];
                        uint32_t* _vpairs_0 = reinterpret_cast<uint32_t*>(&_vld_0[_blk]);
                        #pragma unroll
                        for (int _pair = 0; _pair < 4; _pair++) {
                            (&_vec_load_0[0 + _blk * 8 + _pair * 2])[0] = __uint_as_float(static_cast<uint32_t>(_vpairs_0[_pair]) << 16);
                            (&_vec_load_0[0 + _blk * 8 + _pair * 2])[1] = __uint_as_float(static_cast<uint32_t>(_vpairs_0[_pair]) & 0xffff0000u);
                        }
                    }
                }
                float _vec_load_1[8];
                {
                    const uint4* _vptr_1 = reinterpret_cast<const uint4*>(x + (row * 5376 + col + 8) + 0);
                    uint4 _vld_1[1];
                    #pragma unroll
                    for (int _blk = 0; _blk < 1; _blk++) {
                        _vld_1[_blk] = _vptr_1[_blk];
                        uint32_t* _vpairs_1 = reinterpret_cast<uint32_t*>(&_vld_1[_blk]);
                        #pragma unroll
                        for (int _pair = 0; _pair < 4; _pair++) {
                            (&_vec_load_1[0 + _blk * 8 + _pair * 2])[0] = __uint_as_float(static_cast<uint32_t>(_vpairs_1[_pair]) << 16);
                            (&_vec_load_1[0 + _blk * 8 + _pair * 2])[1] = __uint_as_float(static_cast<uint32_t>(_vpairs_1[_pair]) & 0xffff0000u);
                        }
                    }
                }
                for (int e_1 = 0; e_1 < 8; e_1++) {
                    float xv0 = _vec_load_0[e_1];
                    float xv1 = _vec_load_1[e_1];
                    x_vals[i * 16 + e_1] = xv0;
                    x_vals[i * 16 + 8 + e_1] = xv1;
                    total += xv0 * xv0 + xv1 * xv1;
                }
            }
        }
        for (int stage = 0; stage < 5; stage++) {
            float _shfl_xor_0 = __shfl_xor_sync(0xFFFFFFFF, total, 16 >> stage);
            total += _shfl_xor_0;
        }
        if (lane == 0) {
            partials[warp] = total;
        }
        __syncthreads();
        total = ((lane < 4) ? partials[lane] : 0.0f);
        for (int stage_1 = 0; stage_1 < 2; stage_1++) {
            float _shfl_xor_1 = __shfl_xor_sync(0xFFFFFFFF, total, 2 >> stage_1);
            total += _shfl_xor_1;
        }
        float _shfl_0 = __shfl_sync(0xFFFFFFFF, total, 0);
        total = _shfl_0;
        float _fdiv_rn_0 = __fdiv_rn(total, 5376.0f);
        float _rsqrt_0 = rsqrtf(_fdiv_rn_0 + eps);
        float rstd = _rsqrt_0;
        long long table_row = adaln_index[row];
        int valid = ((table_row >= zero64 && table_row < rows64) ? 1 : 0);
        long long safe_row = ((valid == 1) ? table_row : zero64);
        unsigned long long table_base = (unsigned long long)safe_row * stride64;
        float amax = 0.0f;
        for (int i_1 = 0; i_1 < 3; i_1++) {
            int chunk_1 = tid + i_1 * 128;
            for (int e_2 = 0; e_2 < 16; e_2++) {
                a_vals[i_1 * 16 + e_2] = 0.0f;
            }
            if (chunk_1 < 336) {
                int col_1 = chunk_1 * 16;
                for (int h = 0; h < 2; h++) {
                    float _vec_load_2[8];
                    {
                        const uint4* _vptr_2 = reinterpret_cast<const uint4*>(x_norm_weight + (col_1 + h * 8) + 0);
                        uint4 _vld_2[1];
                        #pragma unroll
                        for (int _blk = 0; _blk < 1; _blk++) {
                            _vld_2[_blk] = _vptr_2[_blk];
                            uint32_t* _vpairs_2 = reinterpret_cast<uint32_t*>(&_vld_2[_blk]);
                            #pragma unroll
                            for (int _pair = 0; _pair < 4; _pair++) {
                                (&_vec_load_2[0 + _blk * 8 + _pair * 2])[0] = __uint_as_float(static_cast<uint32_t>(_vpairs_2[_pair]) << 16);
                                (&_vec_load_2[0 + _blk * 8 + _pair * 2])[1] = __uint_as_float(static_cast<uint32_t>(_vpairs_2[_pair]) & 0xffff0000u);
                            }
                        }
                    }
                    float _vec_load_3[8];
                    {
                        const uint4* _vptr_3 = reinterpret_cast<const uint4*>(adaln_scale + (table_base + (unsigned long long)col_1 + (unsigned long long)(h * 8)) + 0);
                        uint4 _vld_3[1];
                        #pragma unroll
                        for (int _blk = 0; _blk < 1; _blk++) {
                            _vld_3[_blk] = _vptr_3[_blk];
                            uint32_t* _vpairs_3 = reinterpret_cast<uint32_t*>(&_vld_3[_blk]);
                            #pragma unroll
                            for (int _pair = 0; _pair < 4; _pair++) {
                                (&_vec_load_3[0 + _blk * 8 + _pair * 2])[0] = __uint_as_float(static_cast<uint32_t>(_vpairs_3[_pair]) << 16);
                                (&_vec_load_3[0 + _blk * 8 + _pair * 2])[1] = __uint_as_float(static_cast<uint32_t>(_vpairs_3[_pair]) & 0xffff0000u);
                            }
                        }
                    }
                    float _vec_load_4[8];
                    {
                        const uint4* _vptr_4 = reinterpret_cast<const uint4*>(adaln_shift + (table_base + (unsigned long long)col_1 + (unsigned long long)(h * 8)) + 0);
                        uint4 _vld_4[1];
                        #pragma unroll
                        for (int _blk = 0; _blk < 1; _blk++) {
                            _vld_4[_blk] = _vptr_4[_blk];
                            uint32_t* _vpairs_4 = reinterpret_cast<uint32_t*>(&_vld_4[_blk]);
                            #pragma unroll
                            for (int _pair = 0; _pair < 4; _pair++) {
                                (&_vec_load_4[0 + _blk * 8 + _pair * 2])[0] = __uint_as_float(static_cast<uint32_t>(_vpairs_4[_pair]) << 16);
                                (&_vec_load_4[0 + _blk * 8 + _pair * 2])[1] = __uint_as_float(static_cast<uint32_t>(_vpairs_4[_pair]) & 0xffff0000u);
                            }
                        }
                    }
                    float n_raw[8];
                    float sp1_raw[8];
                    for (int e_3 = 0; e_3 < 8; e_3++) {
                        float wv = _vec_load_2[e_3];
                        float sv = _vec_load_3[e_3];
                        n_raw[e_3] = x_vals[i_1 * 16 + h * 8 + e_3] * rstd * wv;
                        sp1_raw[e_3] = sv + 1.0f;
                    }
                    uint32_t n_raw_bf16[4];
                    #pragma unroll
                    for (int _lp = 0; _lp < 4; _lp++) {
                        __nv_bfloat162 _bf2 = __float22bfloat162_rn(make_float2(n_raw[_lp*2 + 0], n_raw[_lp*2+1 + 0]));
                        n_raw_bf16[_lp] = *(uint32_t*)&_bf2;
                    }
                    uint32_t sp1_raw_bf16[4];
                    #pragma unroll
                    for (int _lp = 0; _lp < 4; _lp++) {
                        __nv_bfloat162 _bf2 = __float22bfloat162_rn(make_float2(sp1_raw[_lp*2 + 0], sp1_raw[_lp*2+1 + 0]));
                        sp1_raw_bf16[_lp] = *(uint32_t*)&_bf2;
                    }
                    float n_raw_bf16_f32[8];
                    #pragma unroll
                    for (int _pair = 0; _pair < 4; _pair++) {
                        (&n_raw_bf16_f32[_pair * 2])[0] = __uint_as_float(static_cast<uint32_t>(n_raw_bf16[_pair]) << 16);
                        (&n_raw_bf16_f32[_pair * 2])[1] = __uint_as_float(static_cast<uint32_t>(n_raw_bf16[_pair]) & 0xffff0000u);
                    }
                    float sp1_raw_bf16_f32[8];
                    #pragma unroll
                    for (int _pair = 0; _pair < 4; _pair++) {
                        (&sp1_raw_bf16_f32[_pair * 2])[0] = __uint_as_float(static_cast<uint32_t>(sp1_raw_bf16[_pair]) << 16);
                        (&sp1_raw_bf16_f32[_pair * 2])[1] = __uint_as_float(static_cast<uint32_t>(sp1_raw_bf16[_pair]) & 0xffff0000u);
                    }
                    float a_raw[8];
                    for (int e_4 = 0; e_4 < 8; e_4++) {
                        float bv = _vec_load_4[e_4];
                        a_raw[e_4] = bv + n_raw_bf16_f32[e_4] * sp1_raw_bf16_f32[e_4];
                    }
                    uint32_t a_raw_bf16[4];
                    #pragma unroll
                    for (int _lp = 0; _lp < 4; _lp++) {
                        __nv_bfloat162 _bf2 = __float22bfloat162_rn(make_float2(a_raw[_lp*2 + 0], a_raw[_lp*2+1 + 0]));
                        a_raw_bf16[_lp] = *(uint32_t*)&_bf2;
                    }
                    float a_raw_bf16_f32[8];
                    #pragma unroll
                    for (int _pair = 0; _pair < 4; _pair++) {
                        (&a_raw_bf16_f32[_pair * 2])[0] = __uint_as_float(static_cast<uint32_t>(a_raw_bf16[_pair]) << 16);
                        (&a_raw_bf16_f32[_pair * 2])[1] = __uint_as_float(static_cast<uint32_t>(a_raw_bf16[_pair]) & 0xffff0000u);
                    }
                    for (int e_5 = 0; e_5 < 8; e_5++) {
                        float av = ((valid == 1) ? a_raw_bf16_f32[e_5] : 0.0f);
                        a_vals[i_1 * 16 + h * 8 + e_5] = av;
                        float _fabs_0 = fabsf(av);
                        float _fmax_0 = fmaxf(amax, _fabs_0);
                        amax = _fmax_0;
                    }
                }
            }
        }
        for (int stage_2 = 0; stage_2 < 5; stage_2++) {
            float _shfl_xor_2 = __shfl_xor_sync(0xFFFFFFFF, amax, 16 >> stage_2);
            float _fmax_1 = fmaxf(amax, _shfl_xor_2);
            amax = _fmax_1;
        }
        if (lane == 0) {
            amax_partials[warp] = amax;
        }
        __syncthreads();
        amax = ((lane < 4) ? amax_partials[lane] : 0.0f);
        for (int stage_3 = 0; stage_3 < 2; stage_3++) {
            float _shfl_xor_3 = __shfl_xor_sync(0xFFFFFFFF, amax, 2 >> stage_3);
            float _fmax_2 = fmaxf(amax, _shfl_xor_3);
            amax = _fmax_2;
        }
        float _shfl_1 = __shfl_sync(0xFFFFFFFF, amax, 0);
        amax = _shfl_1;
        float _fmax_3 = fmaxf(amax, 1e-12f);
        amax = _fmax_3;
        float _fdiv_rn_1 = __fdiv_rn(amax, 448.0f);
        float scale = _fdiv_rn_1;
        if (tid == 0) {
            *(reinterpret_cast<float*>(act_scale + row) + (0)) = scale;
        }
        for (int i_2 = 0; i_2 < 3; i_2++) {
            int chunk_2 = tid + i_2 * 128;
            if (chunk_2 < 336) {
                unsigned int words[4];
                for (int w = 0; w < 4; w++) {
                    float _fdiv_rn_2 = __fdiv_rn(a_vals[i_2 * 16 + w * 4], scale);
                    float q_a = _fdiv_rn_2;
                    float _fdiv_rn_3 = __fdiv_rn(a_vals[i_2 * 16 + w * 4 + 1], scale);
                    float q_b = _fdiv_rn_3;
                    float _fdiv_rn_4 = __fdiv_rn(a_vals[i_2 * 16 + w * 4 + 2], scale);
                    float q_c = _fdiv_rn_4;
                    float _fdiv_rn_5 = __fdiv_rn(a_vals[i_2 * 16 + w * 4 + 3], scale);
                    float q_d = _fdiv_rn_5;
                    uint16_t _e4m3x2_f32_0;
                    asm("cvt.rn.satfinite.e4m3x2.f32 %0, %1, %2;" : "=h"(_e4m3x2_f32_0) : "f"(q_b), "f"(q_a));
                    uint16_t _e4m3x2_f32_1;
                    asm("cvt.rn.satfinite.e4m3x2.f32 %0, %1, %2;" : "=h"(_e4m3x2_f32_1) : "f"(q_d), "f"(q_c));
                    uint32_t _pack_u16x2_0;
                    asm("mov.b32 %0, {%1, %2};" : "=r"(_pack_u16x2_0) : "h"(_e4m3x2_f32_0), "h"(_e4m3x2_f32_1));
                    words[w] = _pack_u16x2_0;
                }
                reinterpret_cast<int4*>(act_q + ((row * 5376 + chunk_2 * 16) / 4))[0] = reinterpret_cast<int4*>(words)[0];
            }
        }
        __syncthreads();
    }
}

