namespace h3_mlp_norm_adaln_quant_nvfp4_sm120a {

__device__ __forceinline__ int make_warp_uniform(int x) {
    int result;
    asm volatile("shfl.sync.idx.b32 %0, %1, 0, 0x1F, 0xFFFFFFFF;"
                 : "=r"(result) : "r"(x));
    return result;
}

#define H3_MLP_INF CUDART_INF_F
#define NUM_MAIN_STAGES 1
#define SMEM_PARTIALS_OFF 0
#define SMEM_PARTIALS_STAGE_BYTES 32
#define SMEM_PARTIALS_STRIDE 32
#define SMEM_TOTAL 128
#define THREADS 128
#define LAUNCH_MIN_BLOCKS 4

#include <math_constants.h>

__global__ __launch_bounds__(THREADS, LAUNCH_MIN_BLOCKS) void
kernel_h3_mlp_norm_adaln_quant_nvfp4(__nv_bfloat16* __restrict__ x, __nv_bfloat16* __restrict__ x_norm_weight, __nv_bfloat16* __restrict__ adaln_scale, __nv_bfloat16* __restrict__ adaln_shift, long long* __restrict__ adaln_index, unsigned int* __restrict__ act_q, uint8_t* __restrict__ act_sf, float* __restrict__ act_global_scale, int M, int adaln_rows, long long adaln_row_stride, float eps)
{
    const int tid = threadIdx.x;
    const int warp = make_warp_uniform(tid / 32);
    const int lane = tid % 32;

    extern __shared__ __align__(1024) char smem_raw[];
    int smem;
    smem = (int)(unsigned long long)__cvta_generic_to_shared(smem_raw);

    const int bid = blockIdx.x;
    const int num_bids = gridDim.x;

    const int cta_rank = 0;

    // Kernel setup ops
    float* partials = reinterpret_cast<float*>(smem_raw + SMEM_PARTIALS_OFF);
    const int partials_addr = smem + SMEM_PARTIALS_OFF;

    // === Task calls (dependency order) ===
    float global_scale = act_global_scale[0];
    long long rows64 = (long long)adaln_rows;
    long long zero64 = (long long)0;
    unsigned long long stride64 = (unsigned long long)adaln_row_stride;
    #pragma unroll 1
    for (int row = bid; row < M; row += num_bids) {
        float x_vals[64];
        float total = 0.0f;
        for (int i = 0; i < 2; i++) {
            int slot = tid + i * 128;
            for (int e = 0; e < 32; e++) {
                x_vals[i * 32 + e] = 0.0f;
            }
            if (slot < 168) {
                int col = slot * 32;
                for (int q = 0; q < 4; q++) {
                    float _vec_load_0[8];
                    {
                        const uint4* _vptr_0 = reinterpret_cast<const uint4*>(x + (row * 5376 + col + q * 8) + 0);
                        uint4 _vld_0[1];
                        #pragma unroll
                        for (int _blk = 0; _blk < 1; _blk++) {
                            _vld_0[_blk] = _vptr_0[_blk];
                            uint32_t* _vpairs_0 = reinterpret_cast<uint32_t*>(&_vld_0[_blk]);
                            #pragma unroll
                            for (int _pair = 0; _pair < 4; _pair++) {
                                (&_vec_load_0[0 + _blk * 8 + _pair * 2])[0] = __uint_as_float(static_cast<uint32_t>(_vpairs_0[_pair]) << 16);
                                (&_vec_load_0[0 + _blk * 8 + _pair * 2])[1] = __uint_as_float(static_cast<uint32_t>(_vpairs_0[_pair]) & 0xffff0000u);
                            }
                        }
                    }
                    for (int e_1 = 0; e_1 < 8; e_1++) {
                        float xv = _vec_load_0[e_1];
                        x_vals[i * 32 + q * 8 + e_1] = xv;
                        total += xv * xv;
                    }
                }
            }
        }
        for (int stage = 0; stage < 5; stage++) {
            float _shfl_xor_0 = __shfl_xor_sync(0xFFFFFFFF, total, 16 >> stage);
            total += _shfl_xor_0;
        }
        if (lane == 0) {
            partials[warp] = total;
        }
        __syncthreads();
        total = ((lane < 4) ? partials[lane] : 0.0f);
        for (int stage_1 = 0; stage_1 < 2; stage_1++) {
            float _shfl_xor_1 = __shfl_xor_sync(0xFFFFFFFF, total, 2 >> stage_1);
            total += _shfl_xor_1;
        }
        float _shfl_0 = __shfl_sync(0xFFFFFFFF, total, 0);
        total = _shfl_0;
        float _fdiv_rn_0 = __fdiv_rn(total, 5376.0f);
        float _rsqrt_0 = rsqrtf(_fdiv_rn_0 + eps);
        float rstd = _rsqrt_0;
        long long table_row = adaln_index[row];
        int valid = ((table_row >= zero64 && table_row < rows64) ? 1 : 0);
        long long safe_row = ((valid == 1) ? table_row : zero64);
        unsigned long long table_base = (unsigned long long)safe_row * stride64;
        for (int i_1 = 0; i_1 < 2; i_1++) {
            int slot_1 = tid + i_1 * 128;
            if (slot_1 < 168) {
                int col_1 = slot_1 * 32;
                unsigned int words[4];
                for (int blk = 0; blk < 2; blk++) {
