constexpr int64_t kHidden = 5376;
constexpr int64_t kFfn = 14336;
constexpr int64_t kFc1Rows = 28672;  // prepacked FC1 weight rows (128 gate + 128 up per output tile)
constexpr int64_t kSfBlock = 16;
constexpr int64_t kHiddenSf = kHidden / kSfBlock;   // 336 UE4M3 scales per activation row
constexpr int64_t kHiddenPacked = kHidden / 2;      // 2688 E2M1x2 bytes per activation row
constexpr int64_t kFfnSf = kFfn / kSfBlock;         // 896 UE4M3 scales per y row
constexpr int64_t kFfnPacked = kFfn / 2;            // 7168 E2M1x2 bytes per y row
// The FC2 quantization warps address y with 32-bit word indices (row * 7168 words).
constexpr int64_t kMaxRows = 149796;
// FC1 tile configuration.
constexpr int kFc1BlockM = 128;
constexpr int kFc1BlockN = 128;
constexpr int kFc1BlockB = 256;
constexpr int kFc1BlockKb = 64;
constexpr int kFc1NTiles = 112;
constexpr int kFc1SfaBoxInner = 16;
constexpr int kFc1SfbRowsPerSfTile = 168;
constexpr int kFc1SfbTmaRows = 4;
constexpr int64_t kFc1NumSfTiles = 224;
constexpr int kFc1Threads = 256;            // FP8 kernels (lead-warp form)
constexpr int kFc1Nvfp4Threads = 384;  // NVFP4 kernel (producer-warpgroup form)
constexpr int kFc1Fp8SmemBytes = 99328;
constexpr int kFc1Fp8MxSmemBytes = 99328;
constexpr int kFc1Nvfp4SmemBytes = 93184;
// FC2 tile configuration (K = 14336).
constexpr int kFc2BlockM = 256;
constexpr int kFc2BlockN = 128;
constexpr int kFc2BlockK = 64;
constexpr int kFc2NTiles = 42;
constexpr int kFc2SfaBoxInner = 16;  // UE4M3 y scales per k256 pair of ring stages
constexpr int kFc2SfbRowsPerNTile = 448;
constexpr int kFc2SfbRowsPerKTile = 4;
constexpr int kFc2Threads = 384;
constexpr int kFc2Fp8SmemBytes = 94208;
constexpr int kFc2Fp8MxSmemBytes = 94208;
constexpr int kFc2Nvfp4SmemBytes = 94208;
constexpr int kQuantThreads = 128;
constexpr int kQuantFp8SmemBytes = 128;
constexpr int kQuantNvfp4SmemBytes = 128;

static_assert(kFc1Rows == 2 * kFfn, "prepacked FC1 rows = gate + up");
static_assert(kFc1NumSfTiles * 128 == kFc1Rows, "FC1 weight scale tiles cover the prepacked rows");
static_assert(int64_t{kFc1NTiles} * kFc1BlockN == kFfn, "FC1 output tiles cover the FFN width");
static_assert(int64_t{kFc1SfbRowsPerSfTile} * 256 == 128 * kHiddenSf, "FC1 weight scale tile bytes");
static_assert(int64_t{kFc2NTiles} * kFc2BlockN == kHidden, "FC2 output tiles cover the hidden width");
static_assert(int64_t{kFc2SfbRowsPerNTile} * 256 == int64_t{kFc2BlockN} * kFfnSf, "FC2 weight scale tile bytes");

// Kernel ABIs (parameter order of the generated kernels).
using QuantFp8Kernel = void (*)(__nv_bfloat16*, __nv_bfloat16*, __nv_bfloat16*, __nv_bfloat16*, long long*, unsigned int*, float*, int, int, long long, float);
using QuantNvfp4Kernel = void (*)(__nv_bfloat16*, __nv_bfloat16*, __nv_bfloat16*, __nv_bfloat16*, long long*, unsigned int*, uint8_t*, float*, int, int, long long, float);
using Fc1LegacyKernel = void (*)(const __grid_constant__ CUtensorMap, const __grid_constant__ CUtensorMap, const __grid_constant__ CUtensorMap, const __grid_constant__ CUtensorMap, float*, float*, unsigned int*, int, int, int, float);
using Fc1Kernel = void (*)(const __grid_constant__ CUtensorMap, const __grid_constant__ CUtensorMap, const __grid_constant__ CUtensorMap, const __grid_constant__ CUtensorMap, float*, float*, unsigned int*, unsigned int*, uint8_t*, float*, int, int, int, float);
using Fc2Kernel = void (*)(const __grid_constant__ CUtensorMap, const __grid_constant__ CUtensorMap, const __grid_constant__ CUtensorMap, const __grid_constant__ CUtensorMap, unsigned int*, unsigned int*, uint8_t*, float*, float*, float*, __nv_bfloat16*, long long*, __nv_bfloat16*, unsigned int*, unsigned int*, int, int, int, int, long long, float);
using IndexT = long long;    // the int64 table index element
using StrideT = long long;  // the int64 table row stride

constexpr int kFormLegacy = 0;  // mma.sync.m16n8k32 .f32.e4m3.e4m3.f32 (full rate on the RTX PRO 6000)
constexpr int kFormMx = 2;      // kind::mxf8f6f4.block_scale 1X with unit UE8M0 scales (full rate on GeForce GB202)
constexpr int kFormAuto = -1;

struct DeviceInfo {
  int num_sms;
  bool geforce;  // GB202 GeForce boards halve the FP32-accumulating dense FP8 mma.sync rate
};

struct DeviceTag {};

template <typename Kernel>
void OptIn(Kernel kernel, int bytes) {
  if (bytes > 48 * 1024) minimax_h3_sm120::OptInDynamicSmem(kernel, bytes);
}

DeviceInfo Configure(int device_id) {
  return minimax_h3_sm120::DeviceConfig<DeviceTag, DeviceInfo>::Get(
      "MiniMax-H3 SM120 quantized MLP", device_id, [](const cudaDeviceProp& properties) {
        OptIn(h3_mlp_norm_adaln_quant_fp8_sm120a::kernel_h3_mlp_norm_adaln_quant_fp8, kQuantFp8SmemBytes);
        OptIn(h3_mlp_norm_adaln_quant_nvfp4_sm120a::kernel_h3_mlp_norm_adaln_quant_nvfp4, kQuantNvfp4SmemBytes);
        OptIn(h3_mlp_fc1_fp8_sm120a::kernel_h3_fc1_swiglu_gemm, kFc1Fp8SmemBytes);
        OptIn(h3_mlp_fc1_fp8_mx_sm120a::kernel_h3_mlp_fc1_swiglu_gemm, kFc1Fp8MxSmemBytes);
        OptIn(h3_mlp_fc1_nvfp4_sm120a::kernel_h3_mlp_fc1_swiglu_gemm, kFc1Nvfp4SmemBytes);
        OptIn(h3_mlp_fc2_fp8_sm120a::kernel_h3_mlp_fc2_gemm_fused, kFc2Fp8SmemBytes);
        OptIn(h3_mlp_fc2_fp8_mx_sm120a::kernel_h3_mlp_fc2_gemm_fused, kFc2Fp8MxSmemBytes);
        OptIn(h3_mlp_fc2_nvfp4_sm120a::kernel_h3_mlp_fc2_gemm_fused, kFc2Nvfp4SmemBytes);
        DeviceInfo info{};
        info.num_sms = properties.multiProcessorCount;
        info.geforce = std::strstr(properties.name, "GeForce") != nullptr;
        return info;
      });
}

int ResolveFp8Form(int64_t requested, const DeviceInfo& info) {
  TVM_FFI_CHECK(requested == kFormAuto || requested == kFormLegacy || requested == kFormMx, ValueError)
      << "fp8_mma_form must be -1 (per board), 0 (legacy) or 2 (kind::mxf8f6f4 with unit scales)";
  if (requested != kFormAuto) return static_cast<int>(requested);
  return info.geforce ? kFormMx : kFormLegacy;
}

using minimax_h3_sm120::CheckTensor;
using minimax_h3_sm120::EncodeByteTile;

struct Tables {
  const __nv_bfloat16* scale;
  const __nv_bfloat16* shift;
  const __nv_bfloat16* gate;
  int rows;
  StrideT adaln_row_stride;  // elements between table rows (adaln_scale and adaln_shift share it)
  StrideT gate_row_stride;
};

// The three [rows, 5376] BF16 tables: unit column stride, one common row count, 16-byte-aligned base and row
// pitch; contiguous tables and column chunks of a wider [rows, k * 5376] projection both qualify.
Tables CheckTables(const TensorView& adaln_scale, const TensorView& adaln_shift, const TensorView& gate,
                   DLDevice device) {
  Tables tables{};
  const TensorView* views[3] = {&adaln_scale, &adaln_shift, &gate};
  const char* names[3] = {"adaln_scale", "adaln_shift", "gate"};
  for (int i = 0; i < 3; ++i) {
    const TensorView& t = *views[i];
    minimax_h3_sm120::CheckDevice(t, names[i], device, "x");
    TVM_FFI_CHECK(encode_dlpack_dtype(t.dtype()) == encode_dlpack_dtype(dl_bfloat16), ValueError)
        << names[i] << " must be bfloat16";
    TVM_FFI_CHECK(t.ndim() == 2 && t.size(0) >= 1 && t.size(1) == kHidden, ValueError)
        << names[i] << " must be a [rows, 5376] view with rows >= 1";
    TVM_FFI_CHECK(t.stride(1) == 1 && t.stride(0) % 8 == 0, ValueError)
        << names[i] << " needs a unit column stride and a 16-byte-aligned row pitch";
    TVM_FFI_CHECK((t.size(0) - 1) * t.stride(0) + kHidden < (int64_t{1} << 40), ValueError)
        << names[i] << " span is out of range";
    if (i == 0) {
      tables.rows = static_cast<int>(t.size(0));
    } else {
      TVM_FFI_CHECK(t.size(0) == tables.rows, ValueError) << "adaln_scale, adaln_shift and gate must share one row count";
    }
  }
  TVM_FFI_CHECK(adaln_shift.stride(0) == adaln_scale.stride(0), ValueError)
      << "adaln_scale and adaln_shift must share one row stride";
  tables.scale = static_cast<const __nv_bfloat16*>(adaln_scale.data_ptr());
  tables.shift = static_cast<const __nv_bfloat16*>(adaln_shift.data_ptr());
  tables.gate = static_cast<const __nv_bfloat16*>(gate.data_ptr());
  tables.adaln_row_stride = static_cast<StrideT>(adaln_scale.stride(0));
  tables.gate_row_stride = static_cast<StrideT>(gate.stride(0));
  return tables;
}

struct Plan {
  int quant_grid;
  int fc1_grid;
  int fc1_num_m_tiles;
  int fc1_total_tiles;
  int fc2_grid;
  int fc2_num_m_tiles;
  int fc2_total_tiles;
};

// Mirrors the Python launch_plan(): quantization 8 CTAs per SM (at most one per row), one persistent CTA per SM
// for each GEMM (at most one per tile).
Plan MakePlan(int64_t rows, int num_sms) {
  const auto fc1 = minimax_h3_sm120::MakeGemmLaunchPlan(rows, num_sms, kFc1BlockM, kFc1NTiles, 8);
  const auto fc2 = minimax_h3_sm120::MakeGemmLaunchPlan(rows, num_sms, kFc2BlockM, kFc2NTiles, 8);
  Plan plan{};
  plan.quant_grid = fc1.quant_grid;
  plan.fc1_grid = fc1.gemm_grid;
  plan.fc1_num_m_tiles = fc1.num_m_tiles;
  plan.fc1_total_tiles = fc1.total_tiles;
  plan.fc2_grid = fc2.gemm_grid;
  plan.fc2_num_m_tiles = fc2.num_m_tiles;
  plan.fc2_total_tiles = fc2.total_tiles;
  return plan;
}

struct CommonArgs {
  int64_t rows;
  DLDevice device;
  cudaStream_t stream;
  DeviceInfo info;
  Plan plan;
  Tables tables;
  const __nv_bfloat16* x;
  const __nv_bfloat16* x_norm_weight;
  const IndexT* index;
  const __nv_bfloat16* residual;
  unsigned int* out;
  unsigned int* flags;
};

// Shared validation of the BF16 operands, the tables, the index, the FC2 tile flags and the caller-owned BF16
// [M, 5376] output (which may alias residual or x: the epilogue reads a row's residual before it writes it).
CommonArgs CheckCommon(const TensorView& x, const TensorView& x_norm_weight, const TensorView& adaln_scale,
                       const TensorView& adaln_shift, const TensorView& adaln_index, const TensorView& gate,
                       const TensorView& residual, const TensorView& workspace_flags, const TensorView& out) {
  TVM_FFI_CHECK(x.ndim() == 2 && x.size(0) >= 1 && x.size(0) <= kMaxRows && x.size(1) == kHidden, ValueError)
      << "x must be [M, 5376] with 1 <= M <= " << kMaxRows;
  CommonArgs args{};
  args.rows = x.size(0);
  args.device = x.device();
  CheckTensor(x, "x", args.device, dl_bfloat16, {args.rows, kHidden}, "x");
  CheckTensor(x_norm_weight, "x_norm_weight", args.device, dl_bfloat16, {kHidden}, "x");
  CheckTensor(adaln_index, "adaln_index", args.device, dl_int64, {args.rows}, "x");
  CheckTensor(residual, "residual", args.device, dl_bfloat16, {args.rows, kHidden}, "x");
  CheckTensor(out, "out", args.device, dl_bfloat16, {args.rows, kHidden}, "x");
  args.tables = CheckTables(adaln_scale, adaln_shift, gate, args.device);
  args.info = Configure(args.device.device_id);
  args.plan = MakePlan(args.rows, args.info.num_sms);
  CheckTensor(workspace_flags, "workspace_flags", args.device, dl_int32, {args.plan.fc2_num_m_tiles}, "x");
  args.stream = get_stream(args.device);
  args.x = static_cast<const __nv_bfloat16*>(x.data_ptr());
  args.x_norm_weight = static_cast<const __nv_bfloat16*>(x_norm_weight.data_ptr());
  args.index = static_cast<const IndexT*>(adaln_index.data_ptr());
  args.residual = static_cast<const __nv_bfloat16*>(residual.data_ptr());
  args.out = static_cast<unsigned int*>(out.data_ptr());
  args.flags = static_cast<unsigned int*>(workspace_flags.data_ptr());
  return args;
}

void CheckLaunch(const char* what) {
  const cudaError_t status = cudaGetLastError();
  TVM_FFI_CHECK(status == cudaSuccess, RuntimeError) << what << " launch failed: " << cudaGetErrorString(status);
}

// FC2 M-tile ready flags: zero for the in-kernel y quantization (the quantization warps count the finished rows
// per tile), pre-filled with the tile row counts for pre-quantized operands (the quantization warps idle).
void FillFlags(const CommonArgs& args, bool prequantized) {
  const int n = args.plan.fc2_num_m_tiles;
  if (!prequantized) {
    const cudaError_t status = cudaMemsetAsync(args.flags, 0, sizeof(unsigned int) * n, args.stream);
    TVM_FFI_CHECK(status == cudaSuccess, RuntimeError) << "flag zero-fill failed: " << cudaGetErrorString(status);
    return;
  }
  const unsigned int tail = static_cast<unsigned int>(args.rows - int64_t{n - 1} * kFc2BlockM);
  CUresult result = CUDA_SUCCESS;
  if (n > 1) {
    result = cuMemsetD32Async(reinterpret_cast<CUdeviceptr>(args.flags), static_cast<unsigned int>(kFc2BlockM),
                              static_cast<size_t>(n - 1), args.stream);
    TVM_FFI_CHECK(result == CUDA_SUCCESS, RuntimeError) << "flag pre-fill failed: CUresult=" << static_cast<int>(result);
  }
  result = cuMemsetD32Async(reinterpret_cast<CUdeviceptr>(args.flags + (n - 1)), tail, 1, args.stream);
  TVM_FFI_CHECK(result == CUDA_SUCCESS, RuntimeError) << "flag tail fill failed: CUresult=" << static_cast<int>(result);
}

}  // namespace

// FP8 W8A8 route.  x [M, 5376] BF16 -> workspace_a_q [M, 5376] E4M3 + workspace_a_scale [M] FP32 (RN(amax / 448))
// -> y = SwiGLU(BF16(a_q @ fc1_weight_q^T * s_a[m] * s_w1[n])) [M, 14336] BF16 (workspace_y)
// -> y_q [M, 14336] E4M3 + y_scale [M] (per-token, in the FC2 launch) -> o = y_q @ fc2_weight_q^T * s_y[m] * s_w2[n]
// -> out = BF16(residual + BF16(gate[idx] * BF16(o))).
// fc1_weight_q / fc1_weight_scale: the SM120 prepacked FC1 operands of the FC1+SwiGLU operator; fc2_weight_q
// [5376, 14336] E4M3 + fc2_weight_scale [5376] FP32: the per-output-channel quantization of the FC2 weight.
// fp8_mma_form: -1 selects the board's FP8 instruction form (GeForce GB202 -> kind::mxf8f6f4 with unit UE8M0
// scales, RTX PRO 6000 -> the legacy form); 0 / 2 force it.  Both forms compute the identical result.
void minimax_h3_sm120_fp8_mlp(TensorView x, TensorView x_norm_weight, TensorView adaln_scale, TensorView adaln_shift,
                              TensorView adaln_index, TensorView gate, TensorView residual, TensorView fc1_weight_q,
                              TensorView fc1_weight_scale, TensorView fc2_weight_q, TensorView fc2_weight_scale,
                              TensorView workspace_a_q, TensorView workspace_a_scale, TensorView workspace_y,
                              TensorView workspace_y_q, TensorView workspace_y_scale, TensorView workspace_flags,
                              TensorView out, double eps, int64_t fp8_mma_form) {
  const CommonArgs args =
      CheckCommon(x, x_norm_weight, adaln_scale, adaln_shift, adaln_index, gate, residual, workspace_flags, out);
  CheckTensor(fc1_weight_q, "fc1_weight_q", args.device, dl_float8_e4m3fn, {kFc1Rows, kHidden}, "x");
  CheckTensor(fc1_weight_scale, "fc1_weight_scale", args.device, dl_float32, {kFc1Rows}, "x");
  CheckTensor(fc2_weight_q, "fc2_weight_q", args.device, dl_float8_e4m3fn, {kHidden, kFfn}, "x");
  CheckTensor(fc2_weight_scale, "fc2_weight_scale", args.device, dl_float32, {kHidden}, "x");
  CheckTensor(workspace_a_q, "workspace_a_q", args.device, dl_float8_e4m3fn, {args.rows, kHidden}, "x");
  CheckTensor(workspace_a_scale, "workspace_a_scale", args.device, dl_float32, {args.rows}, "x");
  CheckTensor(workspace_y, "workspace_y", args.device, dl_bfloat16, {args.rows, kFfn}, "x");
  CheckTensor(workspace_y_q, "workspace_y_q", args.device, dl_float8_e4m3fn, {args.rows, kFfn}, "x");
  CheckTensor(workspace_y_scale, "workspace_y_scale", args.device, dl_float32, {args.rows}, "x");
  const int form = ResolveFp8Form(fp8_mma_form, args.info);
  ffi::CUDADeviceGuard device_guard(args.device.device_id);

  FillFlags(args, false);
  h3_mlp_norm_adaln_quant_fp8_sm120a::kernel_h3_mlp_norm_adaln_quant_fp8<<<dim3(args.plan.quant_grid), dim3(kQuantThreads), kQuantFp8SmemBytes, args.stream>>>(
      const_cast<__nv_bfloat16*>(args.x), const_cast<__nv_bfloat16*>(args.x_norm_weight),
      const_cast<__nv_bfloat16*>(args.tables.scale), const_cast<__nv_bfloat16*>(args.tables.shift),
      const_cast<IndexT*>(args.index), static_cast<unsigned int*>(workspace_a_q.data_ptr()),
      static_cast<float*>(workspace_a_scale.data_ptr()), static_cast<int>(args.rows), args.tables.rows,
      args.tables.adaln_row_stride, static_cast<float>(eps));
  CheckLaunch("MiniMax-H3 FP8 norm/AdaLN quantization");

  float* a_scale = static_cast<float*>(workspace_a_scale.data_ptr());
  float* w1_scale = static_cast<float*>(fc1_weight_scale.data_ptr());
  unsigned int* y_words = static_cast<unsigned int*>(workspace_y.data_ptr());
  const CUtensorMap fc1_a = EncodeByteTile(workspace_a_q.data_ptr(), kHidden, args.rows, kFc1BlockKb, kFc1BlockM,
                                           CU_TENSOR_MAP_SWIZZLE_64B, "workspace_a_q");
  const CUtensorMap fc1_b = EncodeByteTile(fc1_weight_q.data_ptr(), kHidden, kFc1Rows, kFc1BlockKb, kFc1BlockB,
                                           CU_TENSOR_MAP_SWIZZLE_64B, "fc1_weight_q");
  // The FP8 kernels never issue scale-tile loads; their descriptors only need valid parameter storage.
  const CUtensorMap unused_map{};
  if (form == kFormMx) {
    // The GeForce form lives in the fork of the FC1 kernel: its NVFP4 emission operands are unused here
    // (act_q_w / act_sf_w are never touched; y_global_scale is read once and not applied), so they alias
    // valid buffers of this call.
    h3_mlp_fc1_fp8_mx_sm120a::kernel_h3_mlp_fc1_swiglu_gemm<<<dim3(args.plan.fc1_grid), dim3(kFc1Threads), kFc1Fp8MxSmemBytes, args.stream>>>(
        fc1_a, fc1_b, unused_map, unused_map, a_scale, w1_scale, y_words, y_words,
        static_cast<uint8_t*>(workspace_y.data_ptr()), w1_scale, static_cast<int>(args.rows),
        args.plan.fc1_num_m_tiles, args.plan.fc1_total_tiles, 1.0f);
  } else {
    h3_mlp_fc1_fp8_sm120a::kernel_h3_fc1_swiglu_gemm<<<dim3(args.plan.fc1_grid), dim3(kFc1Threads), kFc1Fp8SmemBytes, args.stream>>>(
        fc1_a, fc1_b, unused_map, unused_map, a_scale, w1_scale, y_words, static_cast<int>(args.rows),
        args.plan.fc1_num_m_tiles, args.plan.fc1_total_tiles, 1.0f);
  }
  CheckLaunch("MiniMax-H3 FP8 FC1+SwiGLU");

  float* y_scale = static_cast<float*>(workspace_y_scale.data_ptr());
  const CUtensorMap fc2_a = EncodeByteTile(workspace_y_q.data_ptr(), kFfn, args.rows, kFc2BlockK, kFc2BlockM,
                                           CU_TENSOR_MAP_SWIZZLE_64B, "workspace_y_q");
  const CUtensorMap fc2_b = EncodeByteTile(fc2_weight_q.data_ptr(), kFfn, kHidden, kFc2BlockK, kFc2BlockN,
                                           CU_TENSOR_MAP_SWIZZLE_64B, "fc2_weight_q");
  // act_sf_w and act_global_scale are the NVFP4 operands of this kernel: never written / read once and not
  // applied in the FP8 form, so they alias valid buffers of this call.
  Fc2Kernel fc2 = form == kFormMx ? h3_mlp_fc2_fp8_mx_sm120a::kernel_h3_mlp_fc2_gemm_fused : h3_mlp_fc2_fp8_sm120a::kernel_h3_mlp_fc2_gemm_fused;
  const int fc2_smem = form == kFormMx ? kFc2Fp8MxSmemBytes : kFc2Fp8SmemBytes;
  fc2<<<dim3(args.plan.fc2_grid), dim3(kFc2Threads), fc2_smem, args.stream>>>(
      fc2_a, fc2_b, unused_map, unused_map, y_words, static_cast<unsigned int*>(workspace_y_q.data_ptr()),
      static_cast<uint8_t*>(workspace_y_q.data_ptr()), y_scale, y_scale,
      static_cast<float*>(fc2_weight_scale.data_ptr()), const_cast<__nv_bfloat16*>(args.tables.gate),
      const_cast<IndexT*>(args.index), const_cast<__nv_bfloat16*>(args.residual), args.out, args.flags,
      static_cast<int>(args.rows), args.plan.fc2_num_m_tiles, args.plan.fc2_total_tiles, args.tables.rows,
      args.tables.gate_row_stride, 1.0f);
  CheckLaunch("MiniMax-H3 FP8 FC2");
}

// NVFP4 route (FlashInfer conventions: block-16 UE4M3 scales, the 128x4 swizzled weight scales).
// x -> workspace_a_q [M, 2688] u8 + workspace_a_sf [M, 336] u8 under a_global_scale [1] FP32 (448 * 6 / amax)
// -> y quantized in the FC1 epilogue: workspace_y_q [M, 7168] u8 + workspace_y_sf [M, 896] u8 under the static
// y_global_scale [1] FP32 -> FC2 block-scaled GEMM -> out = BF16(residual + BF16(gate[idx] * BF16(fc2_alpha * o))).
// fc1_alpha = 1 / (a_global_scale * w1_global_scale) and fc2_alpha = 1 / (y_global_scale * w2_global_scale)
// rescale the block-scaled accumulators before the BF16 rounds.  fc1_weight_q / fc1_scale_tiles: the SM120
// prepacked FC1 operands; fc2_weight_q [5376, 7168] u8 + fc2_weight_sf (5376 * 896 bytes, 128x4 swizzled block
// scales of the [5376, 14336] FC2 weight, addressed as [42 x 448 rows, 256 bytes]).
void minimax_h3_sm120_nvfp4_mlp(TensorView x, TensorView x_norm_weight, TensorView adaln_scale, TensorView adaln_shift,
                                TensorView adaln_index, TensorView gate, TensorView residual,
                                TensorView a_global_scale, TensorView fc1_weight_q, TensorView fc1_scale_tiles,
                                TensorView y_global_scale, TensorView fc2_weight_q, TensorView fc2_weight_sf,
                                TensorView workspace_a_q, TensorView workspace_a_sf, TensorView workspace_y_q,
                                TensorView workspace_y_sf, TensorView workspace_flags, TensorView out, double eps,
                                double fc1_alpha, double fc2_alpha) {
  const CommonArgs args =
      CheckCommon(x, x_norm_weight, adaln_scale, adaln_shift, adaln_index, gate, residual, workspace_flags, out);
  CheckTensor(a_global_scale, "a_global_scale", args.device, dl_float32, {1}, "x");
  CheckTensor(y_global_scale, "y_global_scale", args.device, dl_float32, {1}, "x");
  CheckTensor(fc1_weight_q, "fc1_weight_q", args.device, dl_uint8, {kFc1Rows, kHiddenPacked}, "x");
  minimax_h3_sm120::CheckFlat(fc1_scale_tiles, "fc1_scale_tiles", dl_uint8, "uint8", kFc1Rows * kHiddenSf,
                              args.device, "x");
  CheckTensor(fc2_weight_q, "fc2_weight_q", args.device, dl_uint8, {kHidden, kFfnPacked}, "x");
  minimax_h3_sm120::CheckFlat(fc2_weight_sf, "fc2_weight_sf", dl_uint8, "uint8", kHidden * kFfnSf, args.device, "x");
  CheckTensor(workspace_a_q, "workspace_a_q", args.device, dl_uint8, {args.rows, kHiddenPacked}, "x");
  CheckTensor(workspace_a_sf, "workspace_a_sf", args.device, dl_uint8, {args.rows, kHiddenSf}, "x");
  CheckTensor(workspace_y_q, "workspace_y_q", args.device, dl_uint8, {args.rows, kFfnPacked}, "x");
  CheckTensor(workspace_y_sf, "workspace_y_sf", args.device, dl_uint8, {args.rows, kFfnSf}, "x");
  ffi::CUDADeviceGuard device_guard(args.device.device_id);

  FillFlags(args, true);
  float* a_g = static_cast<float*>(a_global_scale.data_ptr());
  float* y_g = static_cast<float*>(y_global_scale.data_ptr());
  h3_mlp_norm_adaln_quant_nvfp4_sm120a::kernel_h3_mlp_norm_adaln_quant_nvfp4<<<dim3(args.plan.quant_grid), dim3(kQuantThreads), kQuantNvfp4SmemBytes, args.stream>>>(
      const_cast<__nv_bfloat16*>(args.x), const_cast<__nv_bfloat16*>(args.x_norm_weight),
      const_cast<__nv_bfloat16*>(args.tables.scale), const_cast<__nv_bfloat16*>(args.tables.shift),
      const_cast<IndexT*>(args.index), static_cast<unsigned int*>(workspace_a_q.data_ptr()),
      static_cast<uint8_t*>(workspace_a_sf.data_ptr()), a_g, static_cast<int>(args.rows), args.tables.rows,
      args.tables.adaln_row_stride, static_cast<float>(eps));
  CheckLaunch("MiniMax-H3 NVFP4 norm/AdaLN quantization");

  unsigned int* y_q_words = static_cast<unsigned int*>(workspace_y_q.data_ptr());
  uint8_t* y_sf = static_cast<uint8_t*>(workspace_y_sf.data_ptr());
  const CUtensorMap fc1_a = EncodeByteTile(workspace_a_q.data_ptr(), kHiddenPacked, args.rows, kFc1BlockKb, kFc1BlockM,
                                           CU_TENSOR_MAP_SWIZZLE_64B, "workspace_a_q");
  const CUtensorMap fc1_b = EncodeByteTile(fc1_weight_q.data_ptr(), kHiddenPacked, kFc1Rows, kFc1BlockKb, kFc1BlockB,
                                           CU_TENSOR_MAP_SWIZZLE_64B, "fc1_weight_q");
  const CUtensorMap fc1_sfa = EncodeByteTile(workspace_a_sf.data_ptr(), kHiddenSf, args.rows, kFc1SfaBoxInner,
                                             kFc1BlockM, CU_TENSOR_MAP_SWIZZLE_NONE, "workspace_a_sf");
  const CUtensorMap fc1_sfb = EncodeByteTile(fc1_scale_tiles.data_ptr(), 256, kFc1NumSfTiles * kFc1SfbRowsPerSfTile,
                                             256, kFc1SfbTmaRows, CU_TENSOR_MAP_SWIZZLE_NONE, "fc1_scale_tiles");
  // The NVFP4 form applies alpha instead of the per-row / per-column FP8 scales (act_scale / w_scale unused);
  // its BF16 output pointer is unused in the emission mode and aliases the code buffer.
  h3_mlp_fc1_nvfp4_sm120a::kernel_h3_mlp_fc1_swiglu_gemm<<<dim3(args.plan.fc1_grid), dim3(kFc1Nvfp4Threads), kFc1Nvfp4SmemBytes, args.stream>>>(
      fc1_a, fc1_b, fc1_sfa, fc1_sfb, nullptr, nullptr, y_q_words, y_q_words, y_sf, y_g, static_cast<int>(args.rows),
      args.plan.fc1_num_m_tiles, args.plan.fc1_total_tiles, static_cast<float>(fc1_alpha));
  CheckLaunch("MiniMax-H3 NVFP4 FC1+SwiGLU");

  const CUtensorMap fc2_a = EncodeByteTile(workspace_y_q.data_ptr(), kFfnPacked, args.rows, kFc2BlockK, kFc2BlockM,
                                           CU_TENSOR_MAP_SWIZZLE_64B, "workspace_y_q");
  const CUtensorMap fc2_b = EncodeByteTile(fc2_weight_q.data_ptr(), kFfnPacked, kHidden, kFc2BlockK, kFc2BlockN,
                                           CU_TENSOR_MAP_SWIZZLE_64B, "fc2_weight_q");
  const CUtensorMap fc2_sfa = EncodeByteTile(workspace_y_sf.data_ptr(), kFfnSf, args.rows, kFc2SfaBoxInner, kFc2BlockM,
                                             CU_TENSOR_MAP_SWIZZLE_NONE, "workspace_y_sf");
  const CUtensorMap fc2_sfb = EncodeByteTile(fc2_weight_sf.data_ptr(), 256, int64_t{kFc2NTiles} * kFc2SfbRowsPerNTile,
                                             256, kFc2SfbRowsPerKTile, CU_TENSOR_MAP_SWIZZLE_NONE, "fc2_weight_sf");
  // Pre-quantized operands: the in-kernel quantization is idle (y_w unused, flags pre-filled); the FP8 per-row /
  // per-column scale pointers are unused in this form and alias the global scale.
  h3_mlp_fc2_nvfp4_sm120a::kernel_h3_mlp_fc2_gemm_fused<<<dim3(args.plan.fc2_grid), dim3(kFc2Threads), kFc2Nvfp4SmemBytes, args.stream>>>(
      fc2_a, fc2_b, fc2_sfa, fc2_sfb, y_q_words, y_q_words, y_sf, y_g, y_g, y_g,
      const_cast<__nv_bfloat16*>(args.tables.gate), const_cast<IndexT*>(args.index),
      const_cast<__nv_bfloat16*>(args.residual), args.out, args.flags, static_cast<int>(args.rows),
      args.plan.fc2_num_m_tiles, args.plan.fc2_total_tiles, args.tables.rows, args.tables.gate_row_stride,
      static_cast<float>(fc2_alpha));
  CheckLaunch("MiniMax-H3 NVFP4 FC2");
}

TVM_FFI_DLL_EXPORT_TYPED_FUNC(minimax_h3_sm120_fp8_mlp, minimax_h3_sm120_fp8_mlp);
TVM_FFI_DLL_EXPORT_TYPED_FUNC(minimax_h3_sm120_nvfp4_mlp, minimax_h3_sm120_nvfp4_mlp);
// clang-format on
